	/** 
	 * jumpstart the process by instantiating2 Trade
	 */
	protected void jumpStart() throws Throwable {
		LOGGER.info( "\n======== create instances to get the ball rolling  ======== ");

		tradeId = TradeService.getTradeInstance()
		.createTrade( generateNewCommand() )
		.get();

		// ---------------------------------------------
		// set up query subscriptions after the 1st create
		// ---------------------------------------------
		testingStep = "create";
		setUpQuerySubscriptions();

		TradeService.getTradeInstance()
				.createTrade( generateNewCommand() )
				.get();

	}

	/** 
	 * Set up query subscriptions
	 */
	protected void setUpQuerySubscriptions() throws Throwable {
		LOGGER.info( "\n======== Setting Up Query Subscriptions ======== ");
			
		try {            
			subscriber.tradeSubscribe().updates().subscribe(
					  successValue -> {
						  LOGGER.info(successValue.toString());
						  try {
							  LOGGER.info("GetAll update received for Trade : " + successValue.getTradeId());
							  if (successValue.getTradeId().equals(tradeId)) {
								  if (testingStep.equals("create")) {
									  testingStep = "update";
									  update();
								  } else if (testingStep.equals("delete")) {
									  testingStep = "complete";
									  state( getAll().size() == sizeOfTradeList - 1 , "value not deleted from list");
									  LOGGER.info("**********************************************************");
									  LOGGER.info("Trade test completed successfully...");
									  LOGGER.info("**********************************************************\n");
								  }
							  }
						  } catch( Throwable exc ) {
							  LOGGER.warning( exc.getMessage() );
						  }
					  },
					  error -> LOGGER.warning(error.getMessage()),
					  () -> LOGGER.info("Subscription on trade consumed")
					);
			subscriber.tradeSubscribe( tradeId ).updates().subscribe(
					  successValue -> {
						  LOGGER.info(successValue.toString());
						  try {
							  LOGGER.info("GetOne update received for Trade : " + successValue.getTradeId() + " in step " + testingStep);
							  testingStep = "delete";
							  sizeOfTradeList = getAll().size();
							  delete();
						  } catch( Throwable exc ) {
							  LOGGER.warning( exc.getMessage() );
						  }
					  },
					  error -> LOGGER.warning(error.getMessage()),
					  () -> LOGGER.info("Subscription on trade for tradeId consumed")

					);
			

			}
			catch (Exception e) {
				LOGGER.warning( e.getMessage() );
				throw e;
			}
		}
		
		/** 
	 * read a Trade. 
	 */
	protected Trade read() throws Throwable {
		LOGGER.info( "\n======== READ ======== ");
		LOGGER.info( "-- Reading a previously created Trade" );

		Trade entity = null;
		StringBuilder msg = new StringBuilder( "-- Failed to read Trade with primary key" );
		msg.append( tradeId );
		
		TradeFetchOneSummary fetchOneSummary = new TradeFetchOneSummary( tradeId );

		try {
			entity = TradeService.getTradeInstance().getTrade( fetchOneSummary );

			assertNotNull( entity,msg.toString() );

			LOGGER.info( "-- Successfully found Trade " + entity.toString() );
		}
		catch ( Throwable e ) {
			LOGGER.warning( unexpectedErrorMsg );
			LOGGER.warning( msg.toString() + " : " + e );

			throw e;
		}
		
		return entity;
	}

	/** 
	 * updating a Trade.
	 */
	protected void update() throws Throwable {
		LOGGER.info( "\n======== UPDATE ======== ");
		LOGGER.info( "-- Attempting to update a Trade." );

		StringBuilder msg = new StringBuilder( "Failed to update a Trade : " );        
		Trade entity = read();
		UpdateTradeCommand command = generateUpdateCommand();
		command.setTradeId(entity.getTradeId());

		try {            
			assertNotNull( entity, msg.toString() );

			LOGGER.info( "-- Now updating the created Trade." );

			// for use later on...
			tradeId = entity.getTradeId();

			TradeService proxy = TradeService.getTradeInstance();  

			proxy.updateTrade( command ).get();

			LOGGER.info( "-- Successfully saved Trade - " + entity.toString() );
		}
		catch ( Throwable e ) {
			LOGGER.warning( unexpectedErrorMsg );
			LOGGER.warning( msg.toString() + " : primarykey = " + tradeId + " : command -" +  command + " : " + e );

			throw e;
		}
	}

	/** 
	 * delete a Trade.
	 */
	protected void delete() throws Throwable {
		LOGGER.info( "\n======== DELETE ======== ");
		LOGGER.info( "-- Deleting a previously created Trade." );

		Trade entity = null;
		
		try{
		    entity = read(); 
			LOGGER.info( "-- Successfully read Trade with id " + tradeId );            
		}
		catch ( Throwable e ) {
			LOGGER.warning( unexpectedErrorMsg );
			LOGGER.warning( "-- Failed to read Trade with id " + tradeId );

			throw e;
		}

		try{
			TradeService.getTradeInstance().delete( new DeleteTradeCommand( entity.getTradeId() ) ).get();
			LOGGER.info( "-- Successfully deleted Trade with id " + tradeId );            
		}
		catch ( Throwable e ) {
			LOGGER.warning( unexpectedErrorMsg );
			LOGGER.warning( "-- Failed to delete Trade with id " + tradeId );

			throw e;
		}
	}

	/**
	 * get all Trades.
	 */
	protected List<Trade> getAll() throws Throwable {    
		LOGGER.info( "======== GETALL ======== ");
		LOGGER.info( "-- Retrieving Collection of Trades:" );

		StringBuilder msg = new StringBuilder( "-- Failed to get all Trade : " );        
		List<Trade> collection  = new ArrayList<>();

		try {
			// call the static get method on the TradeService
			collection = TradeService.getTradeInstance().getAllTrade();
			assertNotNull( collection, "An Empty collection of Trade was incorrectly returned.");
			
			// Now print out the values
			Trade entity = null;            
			Iterator<Trade> iter = collection.iterator();
			int index = 1;

			while( iter.hasNext() ) {
				// Retrieve the entity   
				entity = iter.next();

				assertNotNull( entity,"-- null entity in Collection." );
				assertNotNull( entity.getTradeId(), "-- entity in Collection has a null primary key" );        

				LOGGER.info( " - " + String.valueOf(index) + ". " + entity.toString() );
				index++;
			}
		}
		catch ( Throwable e ) {
			LOGGER.warning( unexpectedErrorMsg );
			LOGGER.warning( msg.toString() + " : " + e );

			throw e;
		}
		
		return collection;			
	}

